        "operator",
        "analyst"
      ],
      "evidence": [
        "CAC $41,000; ACV $14,000; gross margin 54%; average sales cycle 7 months; NRR ex-top-customer 71% (implying ~29% annual churn); CAC payback 31 months.",
        "CAC $41,000; ACV $14,000; gross margin 54%; NRR ex-top-customer 71% (implied annual churn 29%); 7-month average sales cycle; operator assessment corroborates 31-month CAC payback and $3 spend per $1 ARR acquired."
